<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth_check.php';
require_once __DIR__ . '/../includes/helpers.php';

class BatalhaController {
 private PDO $pdo; private int $uid; private bool $admin;
 private const PROJETOS=['hereamuu','yaimuu','whipala','urihinari'];
 public function __construct(){ exigirAutenticacao(); $this->pdo=ConectarDB(); $this->uid=(int)$GLOBALS['auth_user']['id']; $this->admin=!empty($GLOBALS['auth_user']['isadmin']); }
 private function projeto(string $codigo): ?array { if(!in_array($codigo,self::PROJETOS,true)) return null; $s=$this->pdo->prepare('SELECT * FROM batalha_projetos WHERE codigo=?');$s->execute([$codigo]);return $s->fetch()?:null; }
 private function membro(int $pid): bool { $s=$this->pdo->prepare('SELECT 1 FROM batalha_membros WHERE id_projeto=? AND id_usuario=?');$s->execute([$pid,$this->uid]);return (bool)$s->fetchColumn(); }
 private function exigirMembro(int $pid): bool { if(!$this->membro($pid)){responderJson(403,['erro'=>'Somente membros aprovados deste projeto podem editar.']);return false;}return true; }
 private function exigirAcesso(int $pid): bool { if(!$this->admin&&!$this->membro($pid)){responderJson(403,['erro'=>'É necessário ter participação aprovada neste projeto para visualizar o conteúdo.']);return false;}return true; }
 public function listar(): void {
  $s=$this->pdo->prepare('SELECT p.*, m.id AS membro_id, m.inscricao, so.status AS solicitacao_status FROM batalha_projetos p LEFT JOIN batalha_membros m ON m.id_projeto=p.id AND m.id_usuario=? LEFT JOIN batalha_solicitacoes so ON so.id_projeto=p.id AND so.id_usuario=? ORDER BY p.id');$s->execute([$this->uid,$this->uid]);
  $rows=$s->fetchAll(); foreach($rows as &$r){$r['sou_membro']=(bool)$r['membro_id']||$this->admin;$r['pode_ver']=$r['sou_membro'];unset($r['membro_id']);}unset($r);
  responderJson(200,['projetos'=>$rows,'admin'=>$this->admin]);
 }
 public function solicitar(): void { $d=lerJson()??[];$p=$this->projeto((string)($d['projeto']??''));if(!$p){responderJson(400,['erro'=>'Projeto inválido']);return;}
  $insc=$d['inscricao']??null;if($p['codigo']==='urihinari'&&!in_array($insc,['roteiro','figurino','encenacao'],true)){responderJson(400,['erro'=>'Escolha Roteiro, Figurino ou Encenação.']);return;}if($p['codigo']!=='urihinari')$insc=null;
  $s=$this->pdo->prepare('SELECT status FROM batalha_solicitacoes WHERE id_projeto=? AND id_usuario=?');$s->execute([$p['id'],$this->uid]);$old=$s->fetchColumn();if($old==='aprovada'||$this->membro((int)$p['id'])){responderJson(409,['erro'=>'Você já participa deste projeto.']);return;}if($old==='pendente'){responderJson(409,['erro'=>'Sua solicitação já está aguardando análise.']);return;}
  $q=$this->pdo->prepare("INSERT INTO batalha_solicitacoes(id_projeto,id_usuario,inscricao,status) VALUES(?,?,?,'pendente') ON DUPLICATE KEY UPDATE inscricao=VALUES(inscricao),status='pendente',solicitado_em=CURRENT_TIMESTAMP,analisado_por=NULL,analisado_em=NULL");$q->execute([$p['id'],$this->uid,$insc]);responderJson(201,['sucesso'=>true,'mensagem'=>'Solicitação enviada para aprovação.']);
 }
 public function solicitacoes(): void {if(!$this->admin){responderJson(403,['erro'=>'Acesso restrito a administradores']);return;}$s=$this->pdo->query("SELECT s.id,s.status,s.inscricao,s.solicitado_em,u.nome,u.usuario,p.codigo,p.nome AS projeto FROM batalha_solicitacoes s JOIN usuarios u ON u.id=s.id_usuario JOIN batalha_projetos p ON p.id=s.id_projeto WHERE s.status='pendente' ORDER BY s.solicitado_em");responderJson(200,['solicitacoes'=>$s->fetchAll()]);}
 public function analisar(): void {if(!$this->admin){responderJson(403,['erro'=>'Acesso restrito a administradores']);return;}$d=lerJson()??[];$id=idValido($d['id']??null);$acao=$d['acao']??'';if(!$id||!in_array($acao,['aprovar','recusar'],true)){responderJson(400,['erro'=>'Solicitação ou ação inválida']);return;}$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT * FROM batalha_solicitacoes WHERE id=? AND status='pendente' FOR UPDATE");$s->execute([$id]);$r=$s->fetch();if(!$r){$this->pdo->rollBack();responderJson(404,['erro'=>'Solicitação pendente não encontrada']);return;}$status=$acao==='aprovar'?'aprovada':'recusada';$u=$this->pdo->prepare('UPDATE batalha_solicitacoes SET status=?,analisado_por=?,analisado_em=NOW() WHERE id=?');$u->execute([$status,$this->uid,$id]);if($acao==='aprovar'){$m=$this->pdo->prepare('INSERT INTO batalha_membros(id_projeto,id_usuario,inscricao,aprovado_por) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE inscricao=VALUES(inscricao),aprovado_por=VALUES(aprovado_por),aprovado_em=CURRENT_TIMESTAMP');$m->execute([$r['id_projeto'],$r['id_usuario'],$r['inscricao'],$this->uid]);}$this->pdo->commit();responderJson(200,['sucesso'=>true,'mensagem'=>$acao==='aprovar'?'Participação aprovada.':'Solicitação recusada.']);}catch(Throwable $e){$this->pdo->rollBack();error_log($e->getMessage());responderJson(500,['erro'=>'Não foi possível analisar a solicitação']);}}
 public function conteudo(): void {$p=$this->projeto((string)($_GET['projeto']??''));if(!$p){responderJson(404,['erro'=>'Projeto não encontrado']);return;}if(!$this->exigirAcesso((int)$p['id']))return;$out=['projeto'=>$p];if($p['codigo']==='hereamuu'||$p['codigo']==='whipala'){$out['aviso']='Em desenvolvimento';responderJson(200,$out);return;}
  if($p['codigo']==='yaimuu'){$out['documentos']=$this->documentos((int)$p['id'],['poema','fontes']);}
  if($p['codigo']==='urihinari'){$s=$this->pdo->prepare('SELECT inscricao FROM batalha_membros WHERE id_projeto=? AND id_usuario=?');$s->execute([$p['id'],$this->uid]);$out['inscricao']=$s->fetchColumn()?:null;$out['documentos']=$this->documentos((int)$p['id'],['roteiro']);$f=$this->pdo->prepare('SELECT f.*,u.nome AS autor FROM batalha_figurinos f JOIN usuarios u ON u.id=f.id_usuario WHERE f.id_projeto=? ORDER BY f.id DESC');$f->execute([$p['id']]);$out['figurinos']=$f->fetchAll();foreach($out['figurinos'] as &$fig){$cq=$this->pdo->prepare('SELECT c.id,c.comentario,c.criado_em,u.nome AS autor FROM batalha_figurino_comentarios c JOIN usuarios u ON u.id=c.id_usuario WHERE c.id_figurino=? ORDER BY c.id');$cq->execute([$fig['id']]);$fig['comentarios']=$cq->fetchAll();$fig['url']='/api/batalha/figurinos/arquivo?id='.(int)$fig['id'];}unset($fig);$e=$this->pdo->prepare('SELECT e.*,u.nome AS membro FROM batalha_encenacao e JOIN usuarios u ON u.id=e.id_usuario WHERE e.id_projeto=? ORDER BY e.id');$e->execute([$p['id']]);$out['encenacao']=$e->fetchAll();}
  responderJson(200,$out);
 }
 private function documentos(int $pid,array $keys): array {$marks=implode(',',array_fill(0,count($keys),'?'));$s=$this->pdo->prepare("SELECT d.*,u.nome AS autor FROM batalha_documentos d LEFT JOIN usuarios u ON u.id=d.atualizado_por WHERE d.id_projeto=? AND d.chave IN ($marks)");$s->execute(array_merge([$pid],$keys));$rows=$s->fetchAll();$out=[];foreach($keys as $k)$out[$k]=['conteudo'=>'','versao'=>0,'atualizado_em'=>null];foreach($rows as $r)$out[$r['chave']]=['id'=>(int)$r['id'],'conteudo'=>$r['conteudo'],'versao'=>(int)$this->versao((int)$r['id']),'atualizado_em'=>$r['atualizado_em'],'autor'=>$r['autor']];return $out;}
 private function versao(int $doc): int {$s=$this->pdo->prepare('SELECT COALESCE(MAX(versao),0) FROM batalha_historico WHERE id_documento=?');$s->execute([$doc]);return (int)$s->fetchColumn();}
 public function salvarDocumento(): void {$d=lerJson()??[];$p=$this->projeto((string)($d['projeto']??''));$key=(string)($d['chave']??'');$valid=$p&&(($p['codigo']==='yaimuu'&&in_array($key,['poema','fontes'],true))||($p['codigo']==='urihinari'&&$key==='roteiro'));if(!$valid){responderJson(400,['erro'=>'Documento inválido']);return;}if(!$this->exigirMembro((int)$p['id']))return;$content=$d['conteudo']??null;if(!is_string($content)||mb_strlen($content)>200000){responderJson(400,['erro'=>'Conteúdo inválido (limite de 200 mil caracteres)']);return;}$summary=trim((string)($d['resumo']??'Atualização'));$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT id,conteudo FROM batalha_documentos WHERE id_projeto=? AND chave=? FOR UPDATE');$s->execute([$p['id'],$key]);$doc=$s->fetch();if(!$doc){$i=$this->pdo->prepare('INSERT INTO batalha_documentos(id_projeto,chave,conteudo,atualizado_por) VALUES(?,?,?,?)');$i->execute([$p['id'],$key,'',$this->uid]);$doc=['id'=>(int)$this->pdo->lastInsertId(),'conteudo'=>''];}$docId=(int)$doc['id'];if(hash('sha256',$doc['conteudo'])===hash('sha256',$content)){$this->pdo->commit();responderJson(200,['sucesso'=>true,'mensagem'=>'Nenhuma alteração detectada','versao'=>$this->versao($docId)]);return;}$u=$this->pdo->prepare('UPDATE batalha_documentos SET conteudo=?,atualizado_por=? WHERE id=?');$u->execute([$content,$this->uid,$docId]);$version=$this->versao($docId)+1;$h=$this->pdo->prepare('INSERT INTO batalha_historico(id_documento,versao,conteudo,resumo,id_usuario) VALUES(?,?,?,?,?)');$h->execute([$docId,$version,$content,mb_substr($summary,0,255),$this->uid]);$this->pdo->commit();responderJson(200,['sucesso'=>true,'versao'=>$version]);}catch(Throwable $e){$this->pdo->rollBack();error_log($e->getMessage());responderJson(500,['erro'=>'Falha ao salvar documento']);}}
 public function historico(): void {$p=$this->projeto((string)($_GET['projeto']??''));$key=(string)($_GET['chave']??'');if(!$p||!in_array($key,['poema','fontes','roteiro'],true)){responderJson(400,['erro'=>'Parâmetros inválidos']);return;}if(!$this->exigirAcesso((int)$p['id']))return;$s=$this->pdo->prepare('SELECT id FROM batalha_documentos WHERE id_projeto=? AND chave=?');$s->execute([$p['id'],$key]);$doc=(int)$s->fetchColumn();if(!$doc){responderJson(200,['historico'=>[]]);return;}if(isset($_GET['versao'])){$v=idValido($_GET['versao']);$q=$this->pdo->prepare('SELECT conteudo,versao,resumo,criado_em FROM batalha_historico WHERE id_documento=? AND versao=?');$q->execute([$doc,$v]);$snapshot=$q->fetch();if(!$snapshot){responderJson(404,['erro'=>'Versão não encontrada']);return;}responderJson(200,$snapshot);return;}$q=$this->pdo->prepare('SELECT h.id,h.versao,h.resumo,h.criado_em,u.nome AS autor FROM batalha_historico h JOIN usuarios u ON u.id=h.id_usuario WHERE h.id_documento=? ORDER BY h.versao DESC');$q->execute([$doc]);responderJson(200,['historico'=>$q->fetchAll()]);}
 public function figurinoUpload(): void {$p=$this->projeto('urihinari');if(!$p||!$this->exigirMembro((int)$p['id']))return;$file=$_FILES['imagem']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>8*1024*1024){responderJson(400,['erro'=>'Envie uma imagem de até 8 MB']);return;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null;if(!$ext){responderJson(400,['erro'=>'Formato não permitido']);return;}$name=bin2hex(random_bytes(16)).'.'.$ext;$dir=dirname(__DIR__,2).'/storage/batalha';if(!is_dir($dir))mkdir($dir,0750,true);if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name)){responderJson(500,['erro'=>'Não foi possível armazenar a imagem']);return;}$legenda=trim((string)($_POST['legenda']??''));$s=$this->pdo->prepare('INSERT INTO batalha_figurinos(id_projeto,id_usuario,arquivo,legenda) VALUES(?,?,?,?)');$s->execute([$p['id'],$this->uid,$name,mb_substr($legenda,0,255)]);responderJson(201,['sucesso'=>true,'id'=>(int)$this->pdo->lastInsertId()]);}
 public function comentarioFigurino(): void {$d=lerJson()??[];$id=idValido($d['id_figurino']??null);$txt=trim((string)($d['comentario']??''));$p=$this->projeto('urihinari');if(!$p||!$this->exigirMembro((int)$p['id']))return;if(!$id||$txt===''){responderJson(400,['erro'=>'Comentário obrigatório']);return;}$s=$this->pdo->prepare('SELECT 1 FROM batalha_figurinos WHERE id=? AND id_projeto=?');$s->execute([$id,$p['id']]);if(!$s->fetchColumn()){responderJson(404,['erro'=>'Imagem não encontrada']);return;}$q=$this->pdo->prepare('INSERT INTO batalha_figurino_comentarios(id_figurino,id_usuario,comentario) VALUES(?,?,?)');$q->execute([$id,$this->uid,$txt]);responderJson(201,['sucesso'=>true]);}
 public function arquivoFigurino(): void {$id=idValido($_GET['id']??null);$p=$this->projeto('urihinari');if(!$p||!$this->exigirAcesso((int)$p['id']))return;$s=$this->pdo->prepare('SELECT arquivo FROM batalha_figurinos WHERE id=? AND id_projeto=?');$s->execute([$id,$p['id']]);$file=$s->fetchColumn();if(!$file){http_response_code(404);return;}$path=dirname(__DIR__,2).'/storage/batalha/'.$file;if(!is_file($path)){http_response_code(404);return;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);header('Content-Type: '.$mime);header('X-Content-Type-Options: nosniff');header('Cache-Control: private, max-age=3600');readfile($path);}
 public function comentarios(): void {$id=idValido($_GET['id_figurino']??null);$p=$this->projeto('urihinari');if(!$p||!$this->exigirAcesso((int)$p['id']))return;$s=$this->pdo->prepare('SELECT c.*,u.nome AS autor FROM batalha_figurino_comentarios c JOIN usuarios u ON u.id=c.id_usuario WHERE c.id_figurino=? ORDER BY c.id');$s->execute([$id]);responderJson(200,['comentarios'=>$s->fetchAll()]);}
 public function salvarEncenacao(): void {$p=$this->projeto('urihinari');if(!$p||!$this->exigirMembro((int)$p['id']))return;$d=lerJson()??[];$papel=trim((string)($d['papel']??''));$falas=trim((string)($d['falas']??''));if($papel===''||mb_strlen($papel)>150){responderJson(400,['erro'=>'Informe um papel (máx. 150 caracteres)']);return;}$s=$this->pdo->prepare('INSERT INTO batalha_encenacao(id_projeto,id_usuario,papel,falas) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE papel=VALUES(papel),falas=VALUES(falas)');$s->execute([$p['id'],$this->uid,$papel,$falas]);responderJson(200,['sucesso'=>true]);}
}
